def generate_ratings(movies, users, density=0.55):
    """Generate realistic user-movie ratings with genre-preference weighting."""
    ratings = []
    for user in users:
        preferred = set(user["preferred_genres"].split("|"))
        for movie in movies:
            if np.random.random() > density:
                continue
            movie_genres = set(movie["genres"].split("|"))
            genre_match  = len(preferred & movie_genres) > 0

            # Base: scale IMDb 0-10 → 0-5
            base       = movie["rating"] / 2
            adjustment = np.random.uniform(0.3, 1.0) if genre_match else np.random.uniform(-1.2, 0.0)
            noise      = np.random.normal(0, 0.25)
            rating     = round(np.clip(base + adjustment + noise, 0.5, 5.0) * 2) / 2
            ratings.append({
                "user_id":   user["user_id"],
                "movie_id":  movie["movie_id"],
                "rating":    rating,
                "timestamp": int(np.random.randint(1_300_000_000, 1_750_000_000)),
            })
    return ratings


def save_data(output_dir="data"):
    os.makedirs(output_dir, exist_ok=True)
    # Deduplicate by movie_id
    seen, unique_movies = set(), []
    for m in MOVIES:
        if m["movie_id"] not in seen:
            seen.add(m["movie_id"])
            unique_movies.append(m)

    movies_df  = pd.DataFrame(unique_movies)
    users_df   = pd.DataFrame(USER_PROFILES)
    ratings    = generate_ratings(unique_movies, USER_PROFILES)
    ratings_df = pd.DataFrame(ratings).drop_duplicates(subset=["user_id", "movie_id"])

    movies_df.to_csv(f"{output_dir}/movies.csv",   index=False)
    users_df.to_csv(f"{output_dir}/users.csv",     index=False)
    ratings_df.to_csv(f"{output_dir}/ratings.csv", index=False)
    print(f"✅ Saved {len(movies_df)} movies | {len(users_df)} users | {len(ratings_df)} ratings")
    return movies_df, users_df, ratings_df


if __name__ == "__main__":
    save_data()
